39	// Manages Claude Code agent interactions and language model server lifecycle
40	export class ClaudeAgentManager extends Disposable {
41		private _langModelServer: ClaudeLanguageModelServer | undefined;
42		private _sessions = this._register(new DisposableMap<string, ClaudeCodeSession>());
43	
44		private async getLangModelServer(): Promise<ClaudeLanguageModelServer> {
45			if (!this._langModelServer) {
46				this._langModelServer = this.instantiationService.createInstance(ClaudeLanguageModelServer);
47				await this._langModelServer.start();
48			}
49	
50			return this._langModelServer;
51		}
