61		public async handleRequest(
62			claudeSessionId: string,
63			request: vscode.ChatRequest,
64			_context: vscode.ChatContext,
65			stream: vscode.ChatResponseStream,
66			token: vscode.CancellationToken,
67			isNewSession: boolean,
68			yieldRequested?: () => boolean
69		): Promise<vscode.ChatResult & { claudeSessionId?: string }> {
70			try {
71				// Read UI state from session state service
72				const modelId = this.sessionStateService.getModelIdForSession(claudeSessionId);
73				const permissionMode = this.sessionStateService.getPermissionModeForSession(claudeSessionId);
74				const folderInfo = this.sessionStateService.getFolderInfoForSession(claudeSessionId);
75	
76				if (!modelId || !folderInfo) {
77					throw new Error(`Session state not found for session ${claudeSessionId}. State must be committed before calling handleRequest.`);
78				}
79	
80				// Get server config, start server if needed
81				const langModelServer = await this.getLangModelServer();
82				const serverConfig = langModelServer.getConfig();
83	
84				this.logService.trace(`[ClaudeAgentManager] Handling request for sessionId=${claudeSessionId}, modelId=${modelId.toEndpointModelId()}, permissionMode=${permissionMode}.`);
85				let session: ClaudeCodeSession;
86				if (this._sessions.has(claudeSessionId)) {
87					this.logService.trace(`[ClaudeAgentManager] Reusing Claude session ${claudeSessionId}.`);
88					session = this._sessions.get(claudeSessionId)!;
89				} else {
90					this.logService.trace(`[ClaudeAgentManager] Creating Claude session for sessionId=${claudeSessionId}.`);
91					const newSession = this.instantiationService.createInstance(ClaudeCodeSession, serverConfig, langModelServer, claudeSessionId, modelId, permissionMode, isNewSession);
92					this._sessions.set(claudeSessionId, newSession);
93					session = newSession;
94				}
95	
96				await session.invoke(
97					request,
98					await resolvePromptToContentBlocks(request),
99					request.toolInvocationToken,
100					stream,
101					token,
102					yieldRequested
103				);
104	
105				return {
106					claudeSessionId: session.sessionId
107				};
108			} catch (invokeError) {
109				// Check if this is an abort/cancellation error - don't show these as errors to the user
110				const isAbortError = invokeError instanceof Error && (
111					invokeError.name === 'AbortError' ||
112					invokeError.message?.includes('aborted') ||
113					invokeError.message?.includes('cancelled') ||
114					invokeError.message?.includes('canceled')
115				);
116				if (isAbortError) {
117					this.logService.trace('[ClaudeAgentManager] Request was aborted/cancelled');
118					return { claudeSessionId };
119				}
120	
121				this.logService.error(invokeError as Error);
122				const errorMessage = (invokeError instanceof KnownClaudeError) ? invokeError.message : l10n.t('Claude CLI Error: {0}', invokeError.message);
123				stream.markdown(l10n.t('Error: {0}', errorMessage));
124				return {
125					// This currently can't be used by the sessions API https://github.com/microsoft/vscode/issues/263111
126					errorDetails: { message: errorMessage },
127				};
128			}
129		}
130	}
